"""Compare BatchPQ and a heap oracle on operations generated by BMSSP.

Run from repository root:
    python -m tests.compare_real_queue_extended

Use the identical graph and source for each queue. The heap is a reference,
NOT a drop-in proof of equivalence under the paper's complexity model.
"""
import heapq
import itertools
import json
import math
import random
import statistics
import time

from graphs.graphs import Graph, dijkstra
from graphs.batch_pq import BatchPQ
import graphs.bmssp_frontier_experimental as experiment


class HeapReference:
    def __init__(self, M, B):
        self.M, self.B = M, B
        self._key_val = {}
        self.heap = []
        self.counter = itertools.count()

    def insert(self, vertex, key):
        if vertex in self._key_val and key >= self._key_val[vertex]:
            return
        self._key_val[vertex] = key
        heapq.heappush(self.heap, (key, next(self.counter), vertex))

    def batch_prepend(self, pairs):
        for vertex, key in pairs:
            self.insert(vertex, key)

    def pull(self):
        batch = []
        while self.heap and len(batch) < self.M:
            key, _, vertex = heapq.heappop(self.heap)
            if self._key_val.get(vertex) != key:
                continue
            del self._key_val[vertex]
            batch.append(vertex)
        while self.heap and self._key_val.get(self.heap[0][2]) != self.heap[0][0]:
            heapq.heappop(self.heap)
        boundary = self.heap[0][0] if self.heap else self.B
        return boundary, batch

    def is_empty(self):
        return not self._key_val


def case_graph(n, p, mode, seed):
    rng = random.Random(seed)
    graph = Graph()
    for v in range(n):
        graph.adj[v] = []
    for u in range(n):
        for v in range(n):
            if u == v or rng.random() >= p:
                continue
            w = 0 if mode == "zero" else rng.randint(0, 2) if mode == "small" else rng.randint(1, 20)
            graph.add_edge(u, v, w)
    return graph, rng.randrange(n)


def benchmark(n, p, mode, seed, repetitions=3):
    graph, source = case_graph(n, p, mode, seed)
    reference = dijkstra(graph, source)
    edge_count = sum(map(len, graph.adj.values()))
    result = {"n": n, "p": p, "mode": mode, "seed": seed,
              "source": source, "edges": edge_count}
    original = experiment.BatchPQ
    try:
        for label, queue_type in (("dijkstra", None), ("bmssp_batch", BatchPQ), ("bmssp_heap", HeapReference)):
            samples = []
            status = "correct"
            for _ in range(repetitions):
                experiment.BatchPQ = queue_type or original
                start = time.perf_counter()
                try:
                    distances = (dijkstra(graph, source) if queue_type is None else
                                 experiment.sssp_frontier_experimental(
                                     graph, source, quota_pending_probe=True,
                                     max_iterations=10000))
                except Exception as exc:
                    status = f"{type(exc).__name__}: {exc}"
                    break
                elapsed = (time.perf_counter() - start) * 1000
                samples.append(elapsed)
                if any(distances.get(v, math.inf) != reference[v] for v in reference):
                    status = "incorrect distances"
                    break
            result[label] = {
                "status": status, "samples_ms": samples,
                "median_ms": statistics.median(samples) if samples else None
            }
    finally:
        experiment.BatchPQ = original
    return result


if __name__ == "__main__":
    cases = [
        (64, .12, "zero"), (128, .12, "small"), (256, .03, "zero"),
        (256, .12, "positive"), (512, .03, "small"), (512, .12, "zero"),
    ]
    rows = []
    for n, p, mode in cases:
        seed = 20261017 + n * 17 + int(p * 1000) + {"zero": 0, "small": 1, "positive": 2}[mode]
        row = benchmark(n, p, mode, seed)
        rows.append(row)
        print(json.dumps(row), flush=True)
    with open("real_queue_extended_results.json", "w", encoding="utf-8") as file:
        json.dump(rows, file, indent=2)
